import { ResonixAgent } from './agent.js';
import chalk from 'chalk';
import readline from 'readline';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function printBanner() {
  console.log('');
  console.log(chalk.cyan('  ╔══════════════════════════════════════════╗'));
  console.log(chalk.cyan('  ║') + chalk.bold.white('       R E S O N I X   A G E N T        ') + chalk.cyan('║'));
  console.log(chalk.cyan('  ║') + chalk.gray('     Professional AI Agent with MCP       ') + chalk.cyan('║'));
  console.log(chalk.cyan('  ╚══════════════════════════════════════════╝'));
  console.log('');
  console.log(chalk.gray('  命令:'));
  console.log(chalk.gray('    /status   - 查看 MCP 服务器状态'));
  console.log(chalk.gray('    /memory   - 查看记忆统计'));
  console.log(chalk.gray('    /skills   - 查看可用技能'));
  console.log(chalk.gray('    /clear    - 清除对话历史'));
  console.log(chalk.gray('    /help     - 显示帮助'));
  console.log(chalk.gray('    /exit     - 退出 Agent'));
  console.log('');
}

async function main() {
  printBanner();

  const agent = new ResonixAgent({
    name: 'Resonix',
    model: process.env.OPENAI_MODEL || 'gpt-4o'
  });

  console.log(chalk.yellow('正在初始化 Agent...'));
  try {
    await agent.init();
  } catch (error) {
    console.error(chalk.red('初始化失败: ' + error.message));
    console.log(chalk.yellow('提示: 请检查 .env 文件中的 API Key 配置'));
    console.log(chalk.yellow('你可以复制 .env.example 为 .env 并填入你的 API Key'));
  }

  console.log(chalk.green('
Agent 已就绪! 输入你的问题开始对话。
'));

  const prompt = () => {
    rl.question(chalk.bold.cyan('You> '), async (input) => {
      const trimmed = input.trim();

      if (!trimmed) {
        prompt();
