let content = fs.readFileSync('.reasonix/src/skills.js', 'utf-8');

// Replace ALL cases where \n or \r\n is split across line breaks in string literals
// Strategy: find patterns like '...\r\n' + where the \r\n is actually the line ending
// Replace with: '...' + '\n' +

// Fix pattern: string ending with backslash-linebreak followed by '; on next line
// This is JavaScript string line continuation, not what was intended
content = content.replace(/' \|\\\r?\n\s*';/g, "' |\\n';");
content = content.replace(/'\\|---\\|\\\r?\n\s*';/g, "'|---|\\n';");
content = content.replace(/'\\|\\\r?\n\s*';/g, "'|\\n';");
content = content.replace(/'```json\\\r?\n\s*';/g, "'```json\\n';");
content = content.replace(/'\\\r?\n\s*```'/g, "'\\n```'");
content = content.replace(/\.split\('\\\r?\n'/g, ".split('\\n'");

fs.writeFileSync('.reasonix/src/skills.js', content, 'utf-8');
console.log('Fixed all string split issues');
