let content = fs.readFileSync('.reasonix/src/skills.js', 'utf-8');

// Replace the entire _dataTransform method
const oldDataTransform = content.match(/async _dataTransform.*?(?=async _textAnalyze)/s);
if (oldDataTransform) {
  const newDataTransform = `async _dataTransform(args) {
    const { input, from_format, to_format } = args;
    try {
      let data;
      if (from_format === 'json') {
        data = JSON.parse(input);
      } else {
        data = input;
      }

      if (to_format === 'json') {
        return { success: true, result: JSON.stringify(data, null, 2) };
      } else if (to_format === 'markdown') {
        if (Array.isArray(data)) {
          const keys = Object.keys(data[0] || {});
          const sep = ' | ';
          const NL = String.fromCharCode(10);
          let md = '| # ' + sep + keys.join(sep) + ' |' + NL;
          md += '|---' + sep + keys.map(() => '---').join(sep) + ' |' + NL;
          data.forEach((row, i) => {
            md += '| ' + (i + 1) + sep + Object.values(row).join(sep) + ' |' + NL;
          });
          return { success: true, result: md };
        }
        const BT = String.fromCharCode(96,96,96);
        return { success: true, result: BT + 'json' + NL + JSON.stringify(data, null, 2) + NL + BT };
      }

      return { success: true, result: String(data) };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _textAnalyze`;

content = content.replace(oldDataTransform[0], newDataTransform);
}

fs.writeFileSync('.reasonix/src/skills.js', content, 'utf-8');
console.log('Fixed _dataTransform');
", "path": ".reasonix/fix_strings.mjs"}

