 * Skill Registry - 内置技能注册系统
 * 提供 Agent 无需 MCP 即可使用的核心技能
 */

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import axios from 'axios';

const NL = '\n';
const BT = '```';

export class SkillRegistry {
  constructor(agent) {
    this.agent = agent;
    this.skills = new Map();
  }

  registerBuiltinSkills() {
    this.register('code_execute', {
      description: '执行代码片段并返回结果',
      parameters: {
        type: 'object',
        properties: {
          language: { type: 'string', description: '编程语言: python, javascript, shell' },
          code: { type: 'string', description: '要执行的代码' }
        },
        required: ['language', 'code']
      },
      handler: this._executeCode.bind(this)
    });

    this.register('file_read', {
      description: '读取文件内容',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: '文件路径' },
          encoding: { type: 'string', description: '编码', default: 'utf-8' }
        },
        required: ['path']
      },
      handler: this._readFile.bind(this)
    });

    this.register('file_write', {
      description: '写入文件',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: '文件路径' },
          content: { type: 'string', description: '文件内容' },
          encoding: { type: 'string', description: '编码', default: 'utf-8' }
        },
        required: ['path', 'content']
      },
      handler: this._writeFile.bind(this)
    });

    this.register('file_search', {
      description: '在目录中搜索文件',
      parameters: {
        type: 'object',
        properties: {
          directory: { type: 'string', description: '搜索目录' },
          pattern: { type: 'string', description: '搜索模式 (glob)' },
          content: { type: 'string', description: '搜索文件内容 (regex)' }
        },
        required: ['directory']
      },
      handler: this._searchFiles.bind(this)
    });

    this.register('http_request', {
      description: '发送 HTTP 请求',
      parameters: {
        type: 'object',
        properties: {
          url: { type: 'string', description: '请求 URL' },
          method: { type: 'string', description: 'HTTP 方法', default: 'GET' },
          headers: { type: 'object', description: '请求头' },
          body: { type: 'string', description: '请求体' }
        },
        required: ['url']
      },
      handler: this._httpRequest.bind(this)
    });

    this.register('shell_execute', {
      description: '执行 shell 命令',
      parameters: {
        type: 'object',
        properties: {
          command: { type: 'string', description: 'Shell 命令' },
          cwd: { type: 'string', description: '工作目录' },
          timeout: { type: 'number', description: '超时时间(ms)', default: 30000 }
        },
        required: ['command']
      },
      handler: this._shellExecute.bind(this)
    });

    this.register('data_transform', {
      description: '数据格式转换 (JSON/CSV/YAML/Markdown)',
      parameters: {
        type: 'object',
        properties: {
          input: { type: 'string', description: '输入数据' },
          from_format: { type: 'string', description: '源格式' },
          to_format: { type: 'string', description: '目标格式' }
        },
        required: ['input', 'from_format', 'to_format']
      },
      handler: this._dataTransform.bind(this)
    });

    this.register('text_analyze', {
      description: '文本分析 (统计、提取、摘要)',
      parameters: {
        type: 'object',
        properties: {
          text: { type: 'string', description: '要分析的文本' },
          analysis_type: { type: 'string', description: '分析类型: stats, extract_keywords, summarize' }
        },
        required: ['text', 'analysis_type']
      },
      handler: this._textAnalyze.bind(this)
    });

    this.register('math_calculate', {
      description: '数学表达式计算',
      parameters: {
        type: 'object',
        properties: {
          expression: { type: 'string', description: '数学表达式' }
        },
        required: ['expression']
      },
      handler: this._mathCalculate.bind(this)
    });

    this.register('time_tool', {
      description: '时间相关操作',
      parameters: {
        type: 'object',
        properties: {
          action: { type: 'string', description: '操作: now, format, diff, add' },
