      },
      handler: this._arsConferenceTemplates.bind(this)
    });
    this.register('ars_citation_verifier', {
      description: '5步引用验证防幻觉系统 - APA/IEEE/GB-T7714/MLA/Chicago/ACM',
      parameters: {
        type: 'object',
        properties: {
          action: { type: 'string', description: '操作: verify, step, formats, report' },
          citations: { type: 'array', items: { type: 'object' }, description: '引用列表' },
