    return await skill.handler(args);
  }

  async _executeCode(args) {
    const { language, code } = args;
    try {
      let cmd;
      switch (language) {
        case 'python': cmd = 'python -c "' + code.replace(/"/g, '\\"') + '"'; break;
        case 'javascript': case 'js': cmd = 'node -e "' + code.replace(/"/g, '\\"') + '"'; break;
        case 'shell': cmd = code; break;
        default: throw new Error('不支持的语言: ' + language);
      }
      const result = execSync(cmd, { timeout: 30000, encoding: 'utf-8' });
      return { success: true, output: result };
    } catch (error) { return { success: false, error: error.message }; }
  }

  async _readFile(args) {
    try {
      const content = fs.readFileSync(args.path, args.encoding || 'utf-8');
      return { success: true, content };
    } catch (error) { return { success: false, error: error.message }; }
  }

  async _writeFile(args) {
    try {
      const dir = path.dirname(args.path);
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(args.path, args.content, args.encoding || 'utf-8');
      return { success: true, path: args.path };
    } catch (error) { return { success: false, error: error.message }; }
  }

  async _searchFiles(args) {
    const { directory, pattern, content } = args;
    try {
      let cmd = 'dir /s /b';
      if (pattern) cmd += ' "' + directory + '\\' + pattern + '"';
      else cmd += ' "' + directory + '"';
      const result = execSync(cmd, { timeout: 10000, encoding: 'utf-8' });
      let files = result.trim().split(NL).filter(Boolean);
      if (content) {
        const re = new RegExp(content, 'i');
        files = files.filter(f => { try { return re.test(fs.readFileSync(f, 'utf-8')); } catch { return false; } });
      }
      return { success: true, files: files.slice(0, 50) };
    } catch (error) { return { success: false, error: error.message }; }
  }

  async _httpRequest(args) {
    try {
      const config = {
        method: (args.method || 'GET').toUpperCase(),
        url: args.url,
        headers: args.headers || {},
        timeout: 30000
      };
      if (args.body && config.method !== 'GET') config.data = args.body;
      const response = await axios(config);
      return { success: true, status: response.status, data: typeof response.data === 'string' ? response.data : JSON.stringify(response.data) };
    } catch (error) { return { success: false, error: error.message, status: error.response?.status }; }
  }

  async _shellExecute(args) {
    try {
      const result = execSync(args.command, { timeout: args.timeout || 30000, encoding: 'utf-8', cwd: args.cwd || process.cwd() });
      return { success: true, output: result };
    } catch (error) { return { success: false, error: error.message, stderr: error.stderr?.toString() }; }
  }

  async _dataTransform(args) {
    const { input, from_format, to_format } = args;
    try {
      const data = (from_format === 'json') ? JSON.parse(input) : input;
      if (to_format === 'json') return { success: true, result: JSON.stringify(data, null, 2) };
      if (to_format === 'markdown') {
        if (Array.isArray(data)) {
          const keys = Object.keys(data[0] || {});
          const sep = ' | ';
          let md = '| # ' + sep + keys.join(sep) + ' |' + NL;
          md += '|---' + sep + keys.map(() => '---').join(sep) + ' |' + NL;
          data.forEach((row, i) => { md += '| ' + (i + 1) + sep + Object.values(row).join(sep) + ' |' + NL; });
          return { success: true, result: md };
        }
        return { success: true, result: BT + 'json' + NL + JSON.stringify(data, null, 2) + NL + BT };
      }
      return { success: true, result: String(data) };
    } catch (error) { return { success: false, error: error.message }; }
  }

  async _textAnalyze(args) {
    const { text, analysis_type } = args;
    try {
      switch (analysis_type) {
        case 'stats':
          return { success: true, result: { characters: text.length, words: text.split(/\s+/).filter(Boolean).length, lines: text.split(NL).length, sentences: text.split(/[.!?]+/).filter(Boolean).length } };
        case 'extract_keywords':
          const words = text.toLowerCase().match(/[a-zA-Z\u4e00-\u9fa5]+/g) || [];
          const freq = {};
          words.forEach(w => { freq[w] = (freq[w] || 0) + 1; });
          const keywords = Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 20).map(([w, c]) => ({ word: w, count: c }));
          return { success: true, result: keywords };
        default: return { success: false, error: '不支持的分析类型: ' + analysis_type };
      }
    } catch (error) { return { success: false, error: error.message }; }
  }

  async _mathCalculate(args) {
    const { expression } = args;
    try {
      if (!/^[0-9+\-*/().%\s^]+$/.test(expression)) throw new Error('表达式包含不允许的字符');
      const result = Function('"use strict"; return (' + expression.replace(/\^/g, '**') + ')')();
      return { success: true, result };
    } catch (error) { return { success: false, error: error.message }; }
  }

  async _timeTool(args) {
    const now = new Date();
    switch (args.action) {
      case 'now': return { success: true, result: now.toISOString(), local: now.toLocaleString('zh-CN') };
      case 'format': return { success: true, result: now.toLocaleString('zh-CN', { timeZone: args.timezone }) };
      default: return { success: false, error: '不支持的操作: ' + args.action };
    }
  }

  async _jsonQuery(args) {
    try {
      let obj = typeof args.data === 'string' ? JSON.parse(args.data) : args.data;
      for (const part of args.query.split('.')) {
        if (obj[part] === undefined) return { success: false, error: '路径不存在: ' + part };
        obj = obj[part];
      }
      return { success: true, result: obj };
    } catch (error) { return { success: false, error: error.message }; }
  }

  _runPyScript(dir, scriptName, args) {
    const scriptPath = path.join(process.cwd(), dir, scriptName);
    const tmpFile = path.join(process.cwd(), 'data', '.tmp_' + scriptName + '.json');
    fs.mkdirSync(path.dirname(tmpFile), { recursive: true });
    fs.writeFileSync(tmpFile, JSON.stringify(args), 'utf-8');
    try {
      const r = execSync('python "' + scriptPath + '" "' + tmpFile + '"', { timeout: 60000, encoding: 'utf-8', cwd: process.cwd() });
      try { fs.unlinkSync(tmpFile); } catch {}
      return JSON.parse(r);
    } catch (error) {
      try { fs.unlinkSync(tmpFile); } catch {}
      return { success: false, error: error.message, stderr: error.stderr?.toString() };
    }
  }

  async _excelRead(args) { return this._runPyScript('scripts', 'excel_read.py', args); }
  async _dataClean(args) { return this._runPyScript('scripts', 'data_clean.py', args); }
  async _dataAnalyze(args) { return this._runPyScript('scripts', 'data_analyze.py', args); }
  async _dataVisualize(args) { return this._runPyScript('scripts', 'data_visualize.py', args); }
  async _reportGenerate(args) { return this._runPyScript('scripts', 'report_generate.py', args); }
  async _arsConferenceTemplates(args) { return this._runPyScript('scripts', 'ars_conference_templates.py', args); }
  async _arsCitationVerifier(args) { return this._runPyScript('scripts', 'ars_citation_verifier.py', args); }

  getToolsAsOpenAIFormat() {
    const tools = [];
    for (const [name, skill] of this.skills) {
      tools.push({ type: 'function', function: { name: 'skill__' + name, description: skill.description, parameters: skill.parameters } });
    }
    return tools;
  }
}
