/**
 * Logger - 日志系统
 * 控制台彩色输出 + 文件持久化
 */

import chalk from 'chalk';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export class Logger {
  constructor() {
    this.logDir = path.join(__dirname, '..', 'logs');
    if (!fs.existsSync(this.logDir)) {
      fs.mkdirSync(this.logDir, { recursive: true });
    }
    this.logFile = path.join(this.logDir, 'agent-' + new Date().toISOString().split('T')[0] + '.log');
  }

  _write(level, message) {
    const timestamp = new Date().toISOString();
    const line = '[' + timestamp + '] [' + level + '] ' + message + '
';
    fs.appendFileSync(this.logFile, line);
  }

  info(message) {
    console.log(chalk.blue('[INFO]') + ' ' + message);
    this._write('INFO', message);
  }

  success(message) {
    console.log(chalk.green('[OK]') + ' ' + message);
    this._write('OK', message);
  }

  warn(message) {
    console.log(chalk.yellow('[WARN]') + ' ' + message);
    this._write('WARN', message);
  }

  error(message) {
    console.log(chalk.red('[ERROR]') + ' ' + message);
    this._write('ERROR', message);
  }

  toolCall(toolName, args) {
    const argsStr = JSON.stringify(args).substring(0, 100);
    console.log(chalk.magenta('[TOOL]') + ' ' + chalk.cyan(toolName) + ' ' + chalk.gray(argsStr));
    this._write('TOOL', toolName + ' ' + argsStr);
  }

  toolResult(toolName, result) {
    const resultStr = (result || '').substring(0, 200);
    console.log(chalk.magenta('[RESULT]') + ' ' + chalk.cyan(toolName) + ' ' + chalk.gray(resultStr));
    this._write('RESULT', toolName + ' ' + resultStr);
  }

  thinking(message) {
    console.log(chalk.yellow('[THINK]') + ' ' + message);
    this._write('THINK', message);
  }
}

