{"content": "import fs from 'fs';

const c = fs.readFileSync('.reasonix/src/skills.js', 'utf-8');
let lines = c.split('\n');

// Detect and fix lines where \n is split across two lines:
// Find all lines ending with backslash (line continuation) followed by a line starting with n'
// These are broken '\n' escape sequences

const result = [];
let skipNext = false;

for (let i = 0; i < lines.length; i++) {
  if (skipNext) { skipNext = false; continue; }

  let line = lines[i];

  // Check if this line ends with a backslash (outside a string context, used as line continuation)
  // and the NEXT line starts with "n'" (the 'n' that got separated from \n)
  const trimmed = line.replace(/\r$/, '');
  if (trimmed.endsWith('\\') && i + 1 < lines.length) {
    const nextLine = lines[i + 1].replace(/\r$/, '');
    // If next line starts with n', this is a broken \n
    if (nextLine.trimStart().startsWith("n'")) {
      // Fix: remove the trailing backslash on this line and prepend 'n' to next line
      // But we need to remove the n from next line
      lines[i + 1] = nextLine.replace(/^\s*n'/, "'");
      // Don't add this line's backslash - instead replace it with literal \n in the string
      // The trailing backslash was acting as line continuation; we need to replace it with \n
      result.push(line.replace(/\\\r?$/, "\\n"));
      continue;
    }

    // Also check: next line starts with just n' after whitespace
    // (for cases like the json block where indentation varies)
    const nextTrimStart = nextLine.trimStart();
    if (nextTrimStart.startsWith("n'")) {
      lines[i + 1] = nextLine.replace(/^\s*n'/, "'");
      result.push(line.replace(/\\\r?$/, "\\n"));
      continue;
    }
  }

  result.push(line);
}

fs.writeFileSync('.reasonix/src/skills.js', result.join('\n'), 'utf-8');
console.log(`Processed ${lines.length} lines, applied inline fixes`);
", "path": ".reasonix/fix_syntax.mjs"}

