{"content": "import fs from 'fs';

// Read raw bytes, convert CRLF -> LF, then fix broken escape sequences
const c = fs.readFileSync('.reasonix/src/skills.js', 'utf-8');

// Step 1: Remove all standalone \r (carriage return) characters
// This converts Windows CRLF to LF, and removes stray CR inside strings
let fixed = c.replace(/\r/g, '');

// Step 2: Fix broken line continuations where \ at end of line was 
// intended to be part of \n but got split by line ending
// Pattern: line ends with \ and next line starts with n'
// These should be \n' on one line
const lines = fixed.split('\n');
const result = [];
let i = 0;
while (i < lines.length) {
  let line = lines[i];
  // Check for broken \n: line ends with trailing single backslash 
  // and next line starts with n' (possibly with whitespace)
  if (line.endsWith('\\') && i + 1 < lines.length) {
    const nextLine = lines[i + 1];
    const nx = nextLine.trimStart();
    if (nx.startsWith("n'")) {
      // Fix: replace the trailing \ + newline + n with just \n
      const indent = nextLine.match(/^\s*/)[0];
      result.push(line.replace(/\\$/, '\\n') + nextLine.replace(/^\s*n/, ''));
      i += 2;
      continue;
    }
  }
  result.push(line);
  i++;
}

fs.writeFileSync('.reasonix/src/skills.js', result.join('\n'), 'utf-8');
console.log('Fixed. Lines:', result.length);
